```js
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error('Not found');
  return rows[0];
}
```

Assumes `db.query` returns a promise — if it's callback-only, wrap it first with `util.promisify(db.query.bind(db))`.
